SELECT CODNAT, DESCRNAT, CODNATPAI, ANALITICA, LEVEL AS NIVEL FROM Natureza WHERE SUBSTR(CODNAT, 1, 1) NOT IN ('8', '9') AND CASE WHEN :VAR_DRE_EMP IS NOT NULL AND LTRIM(RTRIM(:VAR_DRE_EMP)) <> '' THEN CASE WHEN (INSTR(',' || :VAR_DRE_EMP || ',', ',1,') > 0 OR INSTR(',' || :VAR_DRE_EMP || ',', ',2,') > 0) AND CODNAT LIKE '2%' THEN 0 WHEN (INSTR(',' || :VAR_DRE_EMP || ',', ',3,') > 0 OR INSTR(',' || :VAR_DRE_EMP || ',', ',4,') > 0 OR INSTR(',' || :VAR_DRE_EMP || ',', ',5,') > 0 OR INSTR(',' || :VAR_DRE_EMP || ',', ',6,') > 0) AND CODNAT LIKE '3%' THEN 0 ELSE 1 END ELSE 1 END = 1 START WITH CODNATPAI = -999999999 CONNECT BY PRIOR CODNAT = CODNATPAI ORDER SIBLINGS BY CASE WHEN UPPER(DESCRNAT) LIKE '%RECEITA%' THEN 1 WHEN UPPER(DESCRNAT) LIKE '%CUSTO%' THEN 2 WHEN UPPER(DESCRNAT) LIKE '%DESPESA%' THEN 3 WHEN UPPER(DESCRNAT) LIKE '%DEPRECIA%' THEN 4 WHEN UPPER(DESCRNAT) LIKE '%PROVIS%' THEN 5 WHEN UPPER(DESCRNAT) LIKE '%INVESTIMENTO%' THEN 6 ELSE 7 END, CODNAT